/* Ripul website. One stylesheet for every page. */

@font-face {
  font-family: 'Instrument Serif';
  src: url('/fonts/instrument-serif.woff2') format('woff2');
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Instrument Serif';
  src: url('/fonts/instrument-serif-italic.woff2') format('woff2');
  font-weight: 400;
  font-style: italic;
  font-display: swap;
}
@font-face {
  font-family: 'Archivo';
  src: url('/fonts/archivo.woff2') format('woff2');
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

:root {
  --paper: #f8f4ec;
  --paper-deep: #f0e9dc;
  --card: #fffdf9;
  --ink: #23253a;
  --ink-soft: #5b5e73;
  --ink-faint: #8b8d9c;
  --line: rgba(35, 37, 58, 0.12);
  --teal: #1f6f70;
  --teal-soft: #d9e9e6;
  --coral: #e2714f;
  --coral-soft: #fbe3d8;
  --sun: #f1c56f;
  --sun-soft: #fbefd2;
  --lilac: #8d86d6;
  --night: #23253a;
  --night-soft: #2f3250;
  --on-night: #f8f4ec;
  --on-night-soft: rgba(248, 244, 236, 0.72);

  /* The identity's green and lime: rare dashes only (the icon, a working dot, selected text). */
  --brand-green: #2d4829;
  --brand-lime: #aef572;

  --display: 'Instrument Serif', 'Iowan Old Style', Georgia, serif;
  --body: 'Archivo', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;

  --wrap: 1120px;
  --gutter: clamp(20px, 5vw, 48px);
  --radius: 28px;
  --shadow: 0 1px 2px rgba(35, 37, 58, 0.05), 0 18px 44px -18px rgba(35, 37, 58, 0.22);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  /* Instrument Serif has one weight; never fake a bold for it. */
  font-synthesis: none;
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--body);
  font-size: 18px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
}

h1,
h2,
h3 {
  font-family: var(--display);
  font-weight: 400;
  letter-spacing: -0.012em;
  line-height: 1.06;
  margin: 0;
  text-wrap: balance;
}

h1 {
  font-size: clamp(50px, 8.4vw, 108px);
  line-height: 0.98;
}
h2 {
  font-size: clamp(38px, 5.4vw, 68px);
}
h3 {
  font-size: clamp(27px, 2.9vw, 34px);
  line-height: 1.15;
}

h1 em,
h2 em {
  font-style: italic;
  font-weight: 380;
  color: var(--teal);
}

p {
  margin: 0;
  text-wrap: pretty;
}

.wrap {
  width: 100%;
  max-width: calc(var(--wrap) + var(--gutter) * 2);
  margin: 0 auto;
  padding: 0 var(--gutter);
}

.eyebrow {
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--teal);
  margin-bottom: 18px;
}

.lede {
  font-size: clamp(19px, 2vw, 22px);
  line-height: 1.55;
  color: var(--ink-soft);
  max-width: 34em;
}

.skip {
  position: absolute;
  left: -999px;
}
.skip:focus {
  left: 16px;
  top: 16px;
  z-index: 100;
  background: var(--card);
  padding: 10px 16px;
  border-radius: 12px;
}

/* ── Buttons ─────────────────────────────────────────────────────────── */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 16px 28px;
  border-radius: 999px;
  font-family: var(--body);
  font-size: 17px;
  font-weight: 600;
  text-decoration: none;
  border: 1.5px solid transparent;
  transition: transform 0.18s ease, background 0.18s ease, box-shadow 0.18s ease;
  white-space: nowrap;
}
.btn:hover {
  transform: translateY(-2px);
}
.btn-primary {
  background: var(--ink);
  color: var(--paper);
  box-shadow: 0 10px 24px -12px rgba(35, 37, 58, 0.6);
}
.btn-primary:hover {
  background: #15172a;
}
.btn-quiet {
  border-color: var(--line);
  color: var(--ink);
  background: transparent;
}
.btn-quiet:hover {
  background: rgba(35, 37, 58, 0.05);
}
.btn-light {
  background: var(--paper);

