import { isStandaloneRuntime, standaloneWelcomeCapabilities } from '../../../../standalone/runtimeMode';
import React, { useEffect, useMemo } from 'react';
import { Box, Typography } from '@mui/material';
import { useTheme, keyframes, alpha } from '@mui/material/styles';
import { eventBus } from '../../../EventBus';
import { useFeatureScope } from '../../../../context/FeatureScopeContext';
import { usePromptCollectionCached } from '../../../../api/hooks/usePromptCollection';
import { hasSiteKeyConfig } from '../../../hooks/useSiteKeyConfig';
import { useCatchUpProgress } from '../../../hooks/useCatchUpProgress';
import { useChatTabDescriptors } from '../../../stores/chatTabsStore';
import { useUserSettings } from '../../../UserSettingsService';
import { cliChatIdMap } from '../../../../relay/relayUtils';
import { isNativeAppMode } from '../../../../context/ContextFactory';
import { CHAT_STARTERS, chatStarterKind, type ChatStarters, type StarterCapability } from '../../../../config/chatStarters';
import type { WelcomeCapability } from '../../../../config/interfaces';
import type { SuggestedPrompt } from '../../../../api/services/promptCollectionsService';
import { V2EmptyState } from './V2EmptyState';
import { V2StarterScreen } from './V2StarterScreen';

/** The rows for what this chat talks to: an agent in a folder, a shell, or a model. */
function useChatStarters(chatId: string): ChatStarters {
  const descriptors = useChatTabDescriptors();
  const globalModelId = useUserSettings((s) => s.userModelOverride);
  const descriptor = descriptors.find((d) => d.id === chatId || d.sourceChatId === chatId);
  return CHAT_STARTERS[chatStarterKind(descriptor?.modelOverride ?? globalModelId, cliChatIdMap.get(chatId)?.provider)];
}

/** What tapping a starter does: by default it fills the composer and does not send. */
function chooseCapability(chatId: string, cap: Pick<WelcomeCapability, 'title' | 'example' | 'eventName' | 'immediateSubmit' | 'openImagePicker'>) {
  if (cap.eventName) eventBus.emit(cap.eventName, { buttonId: cap.title, chatId, timestamp: Date.now() });
  else if (cap.immediateSubmit) eventBus.emit(`${chatId}:input:submit`, { value: cap.example });
  else if (cap.openImagePicker) eventBus.emit(`${chatId}:input:openImagePicker`, { value: cap.example });
  else eventBus.emit(`${chatId}:input:set`, { value: cap.example });
}

const fadeInUp = keyframes`
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
`;

// Module-level flag: skip animation on remount so the cards don't flicker
// if Suspense or state churn briefly unmounts/remounts the screen.
let capabilitiesHasAnimated = false;

interface CapabilityCardProps {
  icon: string;
  title: string;
  description?: string;
  example: string;
  eventName?: string;
  immediateSubmit?: boolean;
  openImagePicker?: boolean;
  chatId: string;
  accentColor?: string;
  /** A slim row (icon, bold title, muted line) instead of a card with its example — for side rails. */
  compact?: boolean;
  /** Compact rows: fill behind the row (default transparent). */
  promptBackground?: string;
}

const CapabilityCard: React.FC<CapabilityCardProps> = ({
  icon, title, description, example, eventName, immediateSubmit, openImagePicker, chatId, accentColor, compact, promptBackground,
}) => {
  const theme = useTheme();
  const resolvedAccent = accentColor || theme.palette.primary.main;

  const handleClick = () => chooseCapability(chatId, { title, example, eventName, immediateSubmit, openImagePicker });

  if (compact) {
    const pressed = promptBackground ? { filter: 'brightness(0.97)' } : { backgroundColor: theme.palette.action.hover };
    return (
      <Box
        component="button"
        type="button"
        data-ui="V2WelcomeScreen.capabilityRow"
        onClick={handleClick}
        sx={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'flex-start',
          gap: 1.25,
          width: '100%',
          // The host shell's global `button { height }` must not squash the row.
          height: 'auto',
          minHeight: 0,
          textAlign: 'left',
          padding: '10px 12px',
          borderRadius: '10px',
          border: `1px solid ${theme.palette.divider}`,
          backgroundColor: promptBackground || 'transparent',
          color: 'inherit',
          font: 'inherit',
          cursor: 'pointer',
          // A touch screen keeps :hover after a tap, which reads as a chosen row.
          '@media (hover: hover)': { '&:hover': pressed },
          '&:active': pressed,
          '&:focus-visible': { outline: `2px solid ${resolvedAccent}`, outlineOffset: 1 },
        }}
      >
        {/* A fixed tinted square, so glyphs of different widths still line up as a column. */}
        <Box
          sx={{
            width: 28,
            height: 28,
            flexShrink: 0,
            borderRadius: '8px',
            display: 'grid',
            placeItems: 'center',
            bgcolor: alpha(theme.palette.primary.main, theme.palette.mode === 'dark' ? 0.2 : 0.1),
            color: theme.palette.primary.main,
          }}
          data-ui="V2WelcomeScreen.capabilityRow.iconChip"
        >
          <Box component="i" className={`fa ${icon}`} sx={{ fontSize: 13, lineHeight: 1 }} data-ui="V2WelcomeScreen.capabilityRow.icon" />
        </Box>
        <Box sx={{ minWidth: 0, flex: 1, textAlign: 'left' }} data-ui="V2WelcomeScreen.capabilityRow.text">
          <Typography sx={{ fontSize: 13.5, fontWeight: 700, lineHeight: 1.35, color: 'text.primary' }} data-ui="V2WelcomeScreen.capabilityRow.title">
            {title}
          </Typography>
          {description && (
            <Typography sx={{ fontSize: 12.5, color: 'text.secondary', lineHeight: 1.4 }} data-ui="V2WelcomeScreen.capabilityRow.description">
              {description}
            </Typography>
          )}
        </Box>
      </Box>
    );
  }

  return (
    <Box
      data-ui="V2WelcomeScreen.capabilityCard"
      onClick={handleClick}
      sx={{
        padding: 2,
        borderRadius: 2,
        border: `1px solid ${accentColor || theme.palette.divider}`,
        backgroundColor: theme.palette.background.paper,
        cursor: 'pointer',
        transition: 'all 0.2s ease-in-out',
        '&:hover': {
          borderColor: resolvedAccent,
          transform: 'translateY(-2px)',
          boxShadow: theme.shadows[2],
        },
      }}
    >
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5, mb: 1 }}>
        <Box
          component="i"
          className={`fa ${icon}`}
          sx={{ fontSize: '1.25rem', color: resolvedAccent }}
          data-ui="V2WelcomeScreen.capabilityCard.icon"
        />
        <Typography
          variant="subtitle1"
          fontWeight={600}
          data-ui="V2WelcomeScreen.capabilityCard.title"
        >
          {title}
        </Typography>
      </Box>
      {description && (
        <Typography
          variant="body2"
          color="text.secondary"
          sx={{ mb: 1.5 }}
          data-ui="V2WelcomeScreen.capabilityCard.description"
        >
          {description}
        </Typography>
      )}
      {!eventName && (
        <Typography
          variant="body2"
          sx={{
            color: theme.palette.text.secondary,
            fontStyle: 'italic',
            backgroundColor: theme.palette.action.hover,
            padding: 1,
            borderRadius: 1,
            fontSize: '0.8rem',
          }}
          data-ui="V2WelcomeScreen.capabilityCard.example"
        >
          "{example}"
        </Typography>
      )}
    </Box>
  );
};

interface CapabilitiesScreenProps {
  chatId: string;
  capabilities: WelcomeCapability[];
  logoUrl?: string;
  logoWidth?: string;
  title?: string;
  description?: string;
  accentColor?: string;
  textColor?: string;
  backgroundColor?: string;
  bottomPadding?: number;
  /** Compact prompt rows, left-aligned and tighter — for a narrow side rail. */
  compact?: boolean;
  promptBackground?: string;
  /** Start below the native shell's title bar. */
  clearNativeHeader?: boolean;
}

const CapabilitiesScreen: React.FC<CapabilitiesScreenProps> = React.memo(({
  chatId, capabilities, logoUrl, logoWidth, title, description, accentColor, textColor, backgroundColor, bottomPadding, compact, promptBackground, clearNativeHeader,
}) => {
  const animate = !capabilitiesHasAnimated;

  useEffect(() => {
    if (animate) {
      const timer = setTimeout(() => { capabilitiesHasAnimated = true; }, 600);
      return () => clearTimeout(timer);
    }
  }, [animate]);

  return (
    <Box
      data-ui="V2WelcomeScreen.capabilitiesScreen"
      sx={{
        display: 'flex',
        flexDirection: 'column',
        alignItems: compact ? 'stretch' : 'center',
        overflowY: 'auto',
        height: '100%',
        padding: compact ? 2 : 4,
        // The native title bar floats over the web view, as it does over the
        // first message (V2ChatScroller reserves the same inset).
        paddingTop: clearNativeHeader
          ? `calc(var(--native-header-height, env(safe-area-inset-top, 0px)) + ${compact ? 16 : 48}px)`
          : compact ? 2 : 6,
        paddingBottom: bottomPadding ? `${bottomPadding + 66}px` : compact ? 2 : 4,
        boxSizing: 'border-box',
        backgroundColor: backgroundColor || undefined,
      }}
    >
      {logoUrl && logoUrl !== '-' && (
        <Box
          component="img"
          src={logoUrl}
          alt="logo"
          data-ui="V2WelcomeScreen.capabilitiesScreen.logo"
          sx={{
            mb: 2,
            display: 'block',
            width: logoWidth ?? 'auto',
            maxWidth: '100%',
            height: 'auto',
            ...(logoWidth ? {} : { maxHeight: 64 }),
            opacity: animate ? 0 : 1,
            animation: animate ? `${fadeInUp} 0.3s ease-out forwards` : 'none',
          }}
        />
      )}
      {/* "-" hides the title (a header outside the chat already names the agent). */}
      {title !== '-' && <Typography
        variant={compact ? 'subtitle1' : 'h5'}
        fontWeight={compact ? 700 : 600}
        sx={{
          mb: description ? 1 : 1,
          textAlign: compact ? 'left' : 'center',
