/** The rows for what this chat talks to: an agent in a folder, a shell, or a model. */
function useChatStarters(chatId: string): ChatStarters {
  const descriptors = useChatTabDescriptors();
  const globalModelId = useUserSettings((s) => s.userModelOverride);
  const descriptor = descriptors.find((d) => d.id === chatId || d.sourceChatId === chatId);
  return CHAT_STARTERS[chatStarterKind(descriptor?.modelOverride ?? globalModelId, cliChatIdMap.get(chatId)?.provider)];
}

/** What tapping a starter does: by default it fills the composer and does not send. */
function chooseCapability(chatId: string, cap: Pick<WelcomeCapability, 'title' | 'example' | 'eventName' | 'immediateSubmit' | 'openImagePicker'>) {
  if (cap.eventName) eventBus.emit(cap.eventName, { buttonId: cap.title, chatId, timestamp: Date.now() });
  else if (cap.immediateSubmit) eventBus.emit(`${chatId}:input:submit`, { value: cap.example });
  else if (cap.openImagePicker) eventBus.emit(`${chatId}:input:openImagePicker`, { value: cap.example });
