import React, { useEffect, useRef, useState } from 'react';
import { Box, GlobalStyles, Typography } from '@mui/material';
import { keyframes, useTheme } from '@mui/material/styles';

/**
 * What Ripul's own apps show in a chat nobody has written in yet.
 *
 * It takes its look from the public website (website/public/css/site.css): a
 * small label, a serif heading whose last words are in italic, and a short
 * list of plain rows divided by hairlines, each led by a dot of colour instead
 * of an icon. Deliberately quiet: this is the first thing a person sees before
 * every piece of work, and it should read like a page, not a control panel.
 *
 * Presentation only, with no stores, so it can be drawn by itself. The chat it
 * belongs to, what its rows are and what a tap does all come from
 * V2WelcomeScreen. Site-key customers keep their own screen (CapabilitiesScreen
 * there); this one is for the first-party apps alone.
 */
export interface StarterRow {
  title: string;
  description?: string;
  /** Ideas this row opens instead of being a choice itself. */
  more?: { title: string; emphasis?: string; rows: StarterRow[] };
}

interface V2StarterScreenProps {
  /** What this chat talks to, as a few words: "Coding agent". */
  eyebrow?: string;
  title: string;
  /** The words at the end of `title` to set in italic. */
  emphasis?: string;
  rows: StarterRow[];
  /** The row chosen, as its place in `rows`, then its place in that row's `more` when it came from there. */
  onChoose: (path: number[]) => void;
  bottomPadding?: number;
  /** Start below the native shell's title bar. */
  clearNativeHeader?: boolean;
  animate?: boolean;
}

const HEADING = "'Instrument Serif', 'Iowan Old Style', Georgia, serif";
/** The website's headline face, served from public/fonts/site/. Falls back to the system serif where it cannot load. */
const FONT_FACES = `
@font-face { font-family: 'Instrument Serif'; src: url('/fonts/site/instrument-serif.woff2') format('woff2'); font-weight: 400; font-style: normal; font-display: swap; }
