import { Theme } from '@mui/material/styles';
import { darkGradientTheme } from './darkGradientTheme';
import { darkFlatTheme } from './darkFlatTheme';
import { darkMinimalTheme } from './darkMinimalTheme';
import { darkGlassTheme } from './darkGlassTheme';
import { darkNeonTheme } from './darkNeonTheme';
import { darkAuroraTheme } from './darkAuroraTheme';
import { lightTheme } from './lightTheme';
import { ThemeMode, ThemeConfig } from './types';

// Export individual themes
export { darkGradientTheme } from './darkGradientTheme';
export { darkFlatTheme } from './darkFlatTheme';
export { darkMinimalTheme } from './darkMinimalTheme';
export { darkGlassTheme } from './darkGlassTheme';
export { darkNeonTheme } from './darkNeonTheme';
export { darkAuroraTheme } from './darkAuroraTheme';
export { lightTheme } from './lightTheme';

// Export types
export type { ThemeMode, ThemeConfig } from './types';

// Theme configurations
export const themes: Record<ThemeMode, ThemeConfig> = {
  auto: {
    mode: 'auto',
    name: 'Auto (System)',
    theme: darkGradientTheme,
  },
  darkGradient: {
    mode: 'darkGradient',
    name: 'Dark Gradient',
    theme: darkGradientTheme,
  },
  darkFlat: {
    mode: 'darkFlat',
    name: 'Dark Flat',
    theme: darkFlatTheme,
  },
  darkMinimal: {
    mode: 'darkMinimal',
    name: 'Dark Minimal',
    theme: darkMinimalTheme,
  },
  darkGlass: {
    mode: 'darkGlass',
    name: 'Dark Glass',
    theme: darkGlassTheme,
  },
  darkNeon: {
    mode: 'darkNeon',
    name: 'Dark Neon',
    theme: darkNeonTheme,
  },
  darkAurora: {
    mode: 'darkAurora',
    name: 'Dark Aurora',
    theme: darkAuroraTheme,
  },
  light: {
    mode: 'light',
    name: 'Light',
    theme: lightTheme,
  },
};

// Get theme by mode
export const getTheme = (mode: ThemeMode): Theme => {
  return themes[mode]?.theme || darkGradientTheme;
};

// Get theme list for UI
export const getThemeList = (): Array<{ value: ThemeMode; label: string }> => {
  return Object.values(themes).map(config => ({
    value: config.mode,
    label: config.name,
  }));
};

// Default theme
export const defaultTheme: Theme = darkGradientTheme;
export const defaultThemeMode: ThemeMode = 'darkGradient';----SYSTEM----
import type { ThemeMode } from './types';

export type RequestedTheme = 'light' | 'dark' | 'system';
export type ResolvedSystemTheme = 'light' | 'dark';

const REQUESTED_THEME_PARAM_KEYS = ['theme'] as const;
const RESOLVED_THEME_PARAM_KEYS = ['resolvedTheme', 'themeResolved'] as const;
const SESSION_STORAGE_KEY = 'ripul-resolved-system-theme';
const LOCAL_STORAGE_KEY = 'ripul:last-resolved-system-theme';

function toRequestedTheme(value: string | null | undefined): RequestedTheme | null {
  if (value === 'light' || value === 'dark' || value === 'system') {
    return value;
  }
  return null;
}

function toResolvedSystemTheme(value: string | null | undefined): ResolvedSystemTheme | null {
  if (value === 'light' || value === 'dark') {
    return value;
  }
  return null;
}

function getHashParams(): URLSearchParams | null {
  if (typeof window === 'undefined') {
    return null;
  }

  const hash = window.location.hash;
  if (!hash) {
    return null;
  }

  const hashContent = hash.startsWith('#') ? hash.substring(1) : hash;
  const queryIndex = hashContent.indexOf('?');
  if (queryIndex !== -1) {
    return new URLSearchParams(hashContent.substring(queryIndex + 1));
  }

  if (hashContent.includes('=')) {
    return new URLSearchParams(hashContent);
  }

  return null;
}

function getSearchParams(): URLSearchParams | null {
  if (typeof window === 'undefined') {
    return null;
  }
  return new URLSearchParams(window.location.search);
}

function readFirstMatchingParam<T extends string>(
  keys: readonly string[],
  mapper: (value: string | null | undefined) => T | null,
): T | null {
  const sources = [getSearchParams(), getHashParams()];
  for (const params of sources) {
    if (!params) continue;
    for (const key of keys) {
      const value = mapper(params.get(key));
      if (value) {
        return value;
      }
    }
  }
  return null;
}

function isNativeAppThemeContext(): boolean {
  if (typeof window === 'undefined' || typeof navigator === 'undefined') {
    return false;
  }

  if (navigator.userAgent?.includes('RipulNative')) {
    return true;
  }

  const searchParams = getSearchParams();
  if (searchParams?.get('native') === 'true') {
    return true;
  }

  return getHashParams()?.get('native') === 'true';
}

/** Fired on `window` when the native shell reports that its appearance changed. */
export const NATIVE_APPEARANCE_EVENT = 'ripul:native-appearance';

/**
 * Light or dark as the native shell itself reports it (`window.__ripulNativeAppearance`,
 * set before the page runs and kept current by the SDK), or null in a browser
 * and in shells built before 9 October 2026.
 *
 * It outranks the media query because the shell knows its own appearance and
 * WebKit's answer inside it has been wrong: on Mac Catalyst a chat drew dark in
 * a light Mac until a click gave its web view focus.
 */
function getNativeResolvedSystemTheme(): ResolvedSystemTheme | null {
  if (typeof window === 'undefined') {
    return null;
  }
  return toResolvedSystemTheme((window as { __ripulNativeAppearance?: string }).__ripulNativeAppearance);
}

function getMatchMediaResolvedSystemTheme(): ResolvedSystemTheme | null {
  if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') {
    return null;
  }

  return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
}

export function getRequestedThemeFromLocation(): RequestedTheme | null {
  return readFirstMatchingParam(REQUESTED_THEME_PARAM_KEYS, toRequestedTheme);
}

export function getExplicitResolvedSystemTheme(): ResolvedSystemTheme | null {
  return readFirstMatchingParam(RESOLVED_THEME_PARAM_KEYS, toResolvedSystemTheme);
}

export function getCachedResolvedSystemTheme(): ResolvedSystemTheme | null {
  if (typeof window === 'undefined') {
    return null;
  }

  try {
    const sessionValue = toResolvedSystemTheme(sessionStorage.getItem(SESSION_STORAGE_KEY));
    if (sessionValue) {
      return sessionValue;
    }
  } catch {
    // Ignore storage access errors.
  }

  try {
    return toResolvedSystemTheme(localStorage.getItem(LOCAL_STORAGE_KEY));
  } catch {
    return null;
  }
}

